  const starD = (o, i, n)=>{ let d = ''; for(let j = 0; j < n * 2; j++){ const r = j % 2 ? i : o, a = Math.PI * j / n - Math.PI / 2; d += (j ? 'L' : 'M') + f(Math.cos(a) * r) + ' ' + f(Math.sin(a) * r); } return d + 'Z'; };
  const sparkD = 'M0-4.8C.5-1.3 1.3-.5 4.8 0 1.3.5.5 1.3 0 4.8-.5 1.3-1.3.5-4.8 0-1.3-.5-.5-1.3 0-4.8Z';
  /* CODIS-ATMOS-V2: أدوات رسم النقش — حافة مقرمشة (أقواس للداخل)، خطوط تظليل، شريحة حمضيات، مكعّب مقطّع */
  const bumpy = (o, i, n)=>{ let d = ''; for(let j = 0; j <= n; j++){ const a = Math.PI * 2 * j / n, x = f(Math.cos(a) * o), y = f(Math.sin(a) * o); if(!j){ d = 'M' + x + ' ' + y; continue; } const m = Math.PI * 2 * (j - .5) / n; d += 'Q' + f(Math.cos(m) * i) + ' ' + f(Math.sin(m) * i) + ' ' + x + ' ' + y; } return d + 'Z'; };
  const F = (d, fill)=>'<path d="' + d + '" fill="' + fill + '"/>';   /* تعبئة بلا حدّ (طبقات داخلية) */
  const hatch = (arr, c)=>arr.map(d=>L(d, c.k, .32, .5)).join('');
